```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("produkty.txt");
    string nazwa;
    int cena, ilosc;
    int wartosc = 0;
    int sumaCen = 0;
    int n = 0;
    vector<pair<string, int>> drogie;

    while (plik >> nazwa >> cena >> ilosc) {
        wartosc += cena * ilosc;
        sumaCen += cena;
        n++;
        if (cena > 20) drogie.push_back({nazwa, cena});
    }

    cout << "a) Calkowita wartosc magazynu: " << wartosc << " zl" << endl;

    cout << endl << "b) Produkty drozsze niz 20 zl:" << endl;
    for (auto &p : drogie) {
        cout << "   " << p.first << ": " << p.second << " zl" << endl;
    }

    cout << endl << "c) Srednia cena: " << fixed << setprecision(2)
         << (double)sumaCen / n << " zl" << endl;
    return 0;
}
```

Weryfikacja:
a) Wartosc: 5*30+4*50+8*20+25*15+32*10+6*40+9*25+12*35+45*8+15*22 = 150+200+160+375+320+240+225+420+360+330 = 2780
b) Drogie (>20): Ser(25), Szynka(32), Kawa(45)
c) Srednia: (5+4+8+25+32+6+9+12+45+15)/10 = 161/10 = 16.10
